'use strict';
// The AMPLE control panel runs on Electron, installed in electron\ by "ample setup".
//   electron\AMPLE.exe                 Electron's own electron.exe, only RENAMED (never modified),
//                                      so Windows / Smart App Control see the exact published file
//   electron\resources\app\            two tiny generated files that point Electron to our code
//   control\panel\                     the panel itself (main.js, worker.js, preload.js, ui\)
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');
const P = require('./paths');

const DIR = P.p('electron');
const EXE = path.join(DIR, 'AMPLE.exe');

// After installing / updating Electron (safe to run again at any time).
function prepare() {
  if (!fs.existsSync(DIR)) return false;
  const original = path.join(DIR, 'electron.exe');
  if (fs.existsSync(original)) {
    fs.rmSync(EXE, { force: true });
    fs.renameSync(original, EXE);
  }
  const app = path.join(DIR, 'resources', 'app');
  fs.mkdirSync(app, { recursive: true });
  fs.writeFileSync(path.join(app, 'package.json'), JSON.stringify({
    name: 'ample', productName: 'AMPLE', version: '1.0.0', private: true, main: 'index.js',
  }, null, 2) + '\n');
  fs.writeFileSync(path.join(app, 'index.js'),
    "// Generated by AMPLE (control/core/panel.js): start the control panel from control\\panel.\n" +
    "require('../../../control/panel/main.js');\n");
  return true;
}

function open() {
  if (!fs.existsSync(EXE) && !fs.existsSync(path.join(DIR, 'electron.exe'))) {
    throw new Error('The control panel is not installed yet. Run: ample setup');
  }
  prepare();
  const env = { ...process.env };
  delete env.ELECTRON_RUN_AS_NODE; // must start as an app, not as plain Node
  spawn(EXE, [], { cwd: DIR, detached: true, stdio: 'ignore', env }).unref();
}

module.exports = { DIR, EXE, prepare, open };
